#pragma once
static void testExtendedFreeze(const juce::File& root){
 float error=0;int checks=0;
 for(bool midi:{false,true}){
  auto dir=root.getChildFile(midi?"freeze-midi":"freeze-tail");dir.createDirectory();Session s(dir);auto& hosted=s.engine.getDeviceManager().getHostedAudioDeviceInterface();te::HostedAudioDeviceInterface::Parameters params;params.sampleRate=48000;params.blockSize=midi?256:128;params.inputChannels=0;params.outputChannels=2;hosted.initialise(params);hosted.prepareToPlay(48000,params.blockSize);
  if(midi){auto* track=s.addTrack();auto clip=track->insertMIDIClip("Freeze notes",{Session::time(0),Session::time(48000)},nullptr);require(clip!=nullptr,"Freeze MIDI clip failed");s.edit->tempoSequence.getTempo(0)->setBpm(120);clip->getSequence().addNote(60,tracktion::BeatPosition::fromBeats(0.5),tracktion::BeatDuration::fromBeats(1),100,0,nullptr);}else s.importAudio(root.getChildFile("tail/source.wav"),0,0);
  auto path=juce::File(STUDIO_SOURCE_ROOT).getChildFile(midi?"build/backend/StudioMidiFixture_artefacts/Release/VST3/Studio MIDI Timing Fixture.vst3":"build/backend/StudioTestTail_artefacts/Release/VST3/Studio Test Tail.vst3");juce::VST3PluginFormat format;juce::OwnedArray<juce::PluginDescription> types;format.findAllTypesForFile(types,path.getFullPathName());require(types.size()==1,"Extended freeze scan failed");s.engine.getPluginManager().initialise();s.engine.getPluginManager().knownPluginList.addType(*types[0]);
  auto item=s.edit->getPluginCache().createNewPlugin(te::ExternalPlugin::xmlTypeName,*types[0]);auto* external=dynamic_cast<te::ExternalPlugin*>(item.get());require(external!=nullptr,"Extended freeze create failed");s.trackAt(0).pluginList.insertPlugin(item,0,nullptr);external->initialiseFully();require(external->getAudioPluginInstance()!=nullptr,"Extended freeze load failed");auto clipState=s.clips()[0]->state.createCopy();juce::AudioBuffer<float> before;
  auto verify=[&](const char* name){auto output=dir.getChildFile(juce::String(name)+".wav");s.render(output,params.blockSize);auto audio=readWave(output);if(before.getNumSamples()==0)before=audio;else for(int c=0;c<2;++c)for(int i=0;i<48000;++i)error=std::max(error,std::abs(audio.getSample(c,i)-before.getSample(c,i)));require(error<1e-6f,"Extended freeze audio differs");++checks;};
  verify("before");if(midi)require(before.getMagnitude(0,48000)>1e-5f,"MIDI freeze baseline silent");else require(std::abs(before.getSample(0,36000)-0.0005f)<1e-7f,"Tail baseline missing");
  s.save();s.setTrackFrozen(0,true);verify("frozen");s.save();item=nullptr;s.reopen();require(s.trackAt(0).isFrozen(te::Track::individualFreeze),"Extended freeze reopen lost flag");verify("reopened");s.setTrackFrozen(0,false);verify("unfrozen");require(s.clips()[0]->state.isEquivalentTo(clipState),"Extended freeze changed clip");s.save();s.reopen();verify("unfrozen-reopened");
 }
 auto* report=new juce::DynamicObject;juce::var value(report);report->setProperty("checks",checks);report->setProperty("max_error",error);report->setProperty("physical_device_opened",false);root.getChildFile("freeze-extended-result.json").replaceWithText(juce::JSON::toString(value));
}
